  String[] fixtures={"一段短文。","第一段。\n\n第二段。\n\n末尾。","短。\n\n"+repeat("长段落，标点与文字连续排版。",80)+"\n\n尾段。","\n\n开头空行。\n\n","𠀀扩展汉字与emoji😀，跨页不能拆开。"+repeat("正文😀。",60)};
  for(String fixture:fixtures)coverage(new ReaderPaginator(fixture,repeat("长标题",12),w,h,reader.getResources().getDisplayMetrics().density,reader.getResources().getDisplayMetrics().scaledDensity,reader.settings));record("pagination_edge_fixtures",fixtures.length);
  ui(()->{reader.settings.font=20;reader.settings.spacing=1;reader.settings.serif=false;reader.settings.night=false;reader.settings.theme=1;reader.settingChanged();});ready();waitFor(()->reader.layouts.containsKey(1),20,"neighbor reflow prepared");
