  ui(()->reader.open(1,0));ready();ui(()->reader.surface.turn(1));waitFor(()->!reader.surface.animating(),3,"chapter2 second page");int saved=reader.anchor;ui(()->reader.save());reader.getSharedPreferences("reader_checks",0).edit().putInt("saved_offset",saved).commit();
