 void contentProbe()throws Exception{if("true".equals(args.getString("restore_content"))){File backup=new File(output,"content-profile-before-refresh.json");String original;try(InputStream in=new FileInputStream(backup)){original=new String(ProtocolCrypto.read(in),"UTF-8");}getTargetContext().getSharedPreferences("api_profiles",0).edit().putString("content",original).remove("content_reinitialized_at").commit();record("previously_failed_content_profile_restored_for_regression",true);}String beforeProfile=getTargetContext().getSharedPreferences("api_profiles",0).getString("content","");LocalLibrary db=new LocalLibrary(getTargetContext());NovelApi client=new NovelApi(getTargetContext(),db);List<Book> books=db.books(true);assertTrue(!books.isEmpty(),"shelf has a book");Book b=books.get(0);JSONArray chapters=client.directory(b.id,false);JSONObject progress=db.progress(b.id);int start=progress==null?0:progress.optInt("index");for(int i=start;i<chapters.length();i++){String id=chapters.getJSONObject(i).getString("id");if(db.chapter(b.id,id)!=null)continue;record("uncached_chapter_probe",new JSONObject().put("book",b.title).put("book_id",b.id).put("index",i).put("chapter_id",id));JSONObject result;try{result=client.chapter(b.id,id);}catch(NovelApi.EmptyResponse error){record("original_uncached_empty_response",true);if(!"true".equals(args.getString("refresh_content")))throw error;SharedPreferences profiles=getTargetContext().getSharedPreferences("api_profiles",0);String original=profiles.getString("content","");try(Writer backup=new OutputStreamWriter(new FileOutputStream(new File(output,"content-profile-before-refresh.json")),"UTF-8")){backup.write(original);}profiles.edit().remove("content").commit();result=new NovelApi(getTargetContext(),db).chapter(b.id,id);record("same_chapter_after_profile_refresh",true);}assertTrue(result.optString("text").length()>0,"nonempty chapter");record("uncached_chapter_characters",result.getString("text").length());record("live_profile_auto_recovered",!beforeProfile.equals(getTargetContext().getSharedPreferences("api_profiles",0).getString("content","")));launchMain();reader=(ReaderActivity)startActivitySync(new Intent(getTargetContext(),ReaderActivity.class).putExtra("book_id",b.id).putExtra("book_name",b.title).putExtra("chapter_index",i).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ready();assertTrue(reader.chapter.optString("id").equals(id)&&reader.chapter.optString("text").length()>0,"recovered chapter visible in reader");shot("content-recovered");record("recovered_chapter_visible",true);return;}throw new AssertionError("No uncached chapter");}


