 void improvements()throws Exception{
  // Bounded prefetch behavior under controlled cache, cancellation and failures.
  List<String> ids=Arrays.asList("0","1","2","3","4","5","6","7");
  assertTrue(ChapterPrefetcher.window(ids,1).equals(Arrays.asList("3","4","5","6")),"window five ahead excluding immediate neighbor");
  assertTrue(ChapterPrefetcher.window(ids,6).isEmpty(),"window clamps at end");
  List<String> fetched=Collections.synchronizedList(new ArrayList<>());java.util.concurrent.CountDownLatch done=new java.util.concurrent.CountDownLatch(3);
  ChapterPrefetcher unit=new ChapterPrefetcher((b,id)->{fetched.add(id);done.countDown();},(b,id)->id.equals("3"));
  unit.update("book",ids,1);assertTrue(done.await(5,java.util.concurrent.TimeUnit.SECONDS),"warming completes");unit.update("book",ids,1);SystemClock.sleep(150);assertTrue(fetched.equals(Arrays.asList("4","5","6")),"cache skipped and window deduplicated");unit.close();record("prefetch_bounds_cache_skip_dedup",true);
  java.util.concurrent.CountDownLatch entered=new java.util.concurrent.CountDownLatch(1),release=new java.util.concurrent.CountDownLatch(1),finished=new java.util.concurrent.CountDownLatch(1);List<String> cancelled=Collections.synchronizedList(new ArrayList<>());
  ChapterPrefetcher cancel=new ChapterPrefetcher((b,id)->{cancelled.add(id);entered.countDown();release.await(5,java.util.concurrent.TimeUnit.SECONDS);finished.countDown();},(b,id)->false);
  cancel.update("book",ids,0);assertTrue(entered.await(5,java.util.concurrent.TimeUnit.SECONDS),"fetch started");cancel.cancel();release.countDown();assertTrue(finished.await(5,java.util.concurrent.TimeUnit.SECONDS),"inflight finishes safely");SystemClock.sleep(150);assertTrue(cancelled.size()==1,"cancel prevents remaining requests");cancel.close();cancel.update("book",ids,1);SystemClock.sleep(100);assertTrue(cancelled.size()==1,"closed worker stays stopped");record("prefetch_cancel_and_close",true);
  List<String> failures=Collections.synchronizedList(new ArrayList<>());ChapterPrefetcher failed=new ChapterPrefetcher((b,id)->{failures.add(id);throw new IOException("controlled");},(b,id)->false);failed.update("book",ids,0);SystemClock.sleep(200);assertTrue(failures.size()==1,"failure stops warming without repeated requests");failed.close();record("prefetch_failure_stops",true);
  launchMain();assertHome();List<Book> books=main.library.books(true);assertTrue(!books.isEmpty(),"real shelf available");Book recent=null;for(Book b:books){JSONObject pos=main.library.progress(b.id);assertTrue(findDescription(main.getWindow().getDecorView(),"作者："+(b.author.isEmpty()?"未知":b.author))!=null,"shelf author "+b.title);if(pos!=null){assertTrue(findText(main.getWindow().getDecorView(),main.progressLabel(b,pos))!=null||findTextContaining(main.getWindow().getDecorView(),main.progressLabel(b,pos)),"visible progress "+b.title);if(recent==null)recent=b;}}
  assertTrue(recent!=null,"recent reading available");Book candidate=recent;int initialMissing=0;for(Book b:books){JSONObject p=main.library.progress(b.id);JSONArray dir=main.library.directory(b.id);if(p==null||dir==null||p.optInt("index")+5>=dir.length())continue;int n=0;for(int i=p.optInt("index")+1;i<=p.optInt("index")+5;i++)if(!main.library.hasChapter(b.id,dir.optJSONObject(i).optString("id")))n++;if(n>initialMissing){initialMissing=n;candidate=b;}}Book selected=candidate;JSONObject before=main.library.progress(selected.id);record("upcoming_missing_before_open",initialMissing);assertTrue(before.optInt("index")+5<before.optInt("total"),"live cache test has five upcoming chapters");record("home_author_and_catalog_progress",new JSONObject().put("book",selected.title).put("author",selected.author).put("progress",main.progressLabel(selected,before)));shot("improved-home");
  assertTrue(main.progressLabel(selected,new JSONObject().put("index",9).put("total",12)).equals("目录 10 / 12 章"),"catalog position ignores chapter title number");assertTrue(main.progressLabel(selected,new JSONObject().put("index",9)).contains("总数待更新"),"unknown total honest");
  android.graphics.drawable.Drawable icon=getTargetContext().getPackageManager().getApplicationIcon("com.example.yuejie");android.content.pm.ApplicationInfo appInfo=getTargetContext().getPackageManager().getApplicationInfo("com.example.yuejie",0);android.graphics.drawable.Drawable resourceIcon=getTargetContext().getPackageManager().getResourcesForApplication(appInfo).getDrawable(appInfo.icon,null);assertTrue(resourceIcon instanceof android.graphics.drawable.AdaptiveIconDrawable,"adaptive launcher resource");record("miui_launcher_drawable_type",icon.getClass().getName());Bitmap bmp=Bitmap.createBitmap(192,192,Bitmap.Config.ARGB_8888);icon.setBounds(0,0,192,192);icon.draw(new Canvas(bmp));int light=0,dark=0;for(int y=30;y<162;y++)for(int x=30;x<162;x++){int c=bmp.getPixel(x,y);if(Color.red(c)>180)light++;else if(Color.alpha(c)>0)dark++;}assertTrue(light>500&&dark>500,"launcher mark renders foreground and background");try(OutputStream out=new FileOutputStream(new File(output,"installed-icon.png"))){bmp.compress(Bitmap.CompressFormat.PNG,100,out);}bmp.recycle();record("installed_adaptive_icon_renders",true);
  reader=(ReaderActivity)startActivitySync(new Intent(getTargetContext(),ReaderActivity.class).putExtra("book_id",selected.id).putExtra("book_name",selected.title).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ready();int start=reader.index;assertTrue(reader.anchor==before.optInt("offset"),"update preserves exact text anchor");int missing=0;for(int i=start+1;i<=start+5&&i<reader.directory.length();i++)if(!reader.library.hasChapter(selected.id,reader.chapterId(i)))missing++;record("upcoming_chapters_initially_missing",missing);
  waitFor(()->{for(int i=start+1;i<=start+5&&i<reader.directory.length();i++)if(!reader.library.hasChapter(selected.id,reader.chapterId(i)))return false;return true;},100,"next five chapters persist");
  for(Integer i:reader.layouts.keySet())assertTrue(Math.abs(i-start)<=1,"only adjacent layouts in memory");record("next_five_chapters_cached",new JSONObject().put("book",selected.title).put("starting_index",start).put("initially_missing",initialMissing));shot("prefetch-reader");
  NovelApi fresh=new NovelApi(getTargetContext(),new LocalLibrary(getTargetContext()));StrictMode.ThreadPolicy old=StrictMode.getThreadPolicy();StrictMode.setThreadPolicy(new StrictMode.ThreadPolicy.Builder().detectNetwork().penaltyDeathOnNetwork().build());try{for(int i=start+1;i<=start+5&&i<reader.directory.length();i++)assertTrue(!fresh.chapter(selected.id,reader.chapterId(i)).optString("text").isEmpty(),"prefetched chapter reads offline");assertTrue(fresh.sessionKey==null,"disk cache needs no session key");}finally{StrictMode.setThreadPolicy(old);}record("five_cached_chapters_network_forbidden",true);
  ui(()->reader.finish());waitFor(()->main.hasWindowFocus(),5,"home resumes");assertTrue(main.library.progress(selected.id).optString("chapter").equals(before.optString("chapter"))&&main.library.progress(selected.id).optInt("offset")==before.optInt("offset"),"reading position retained");assertHome();shot("improved-final-home");record("books_and_reading_position_preserved",books.size());
 }
 boolean findTextContaining(View view,String text){if(view instanceof TextView&&((TextView)view).getText().toString().contains(text))return true;if(view instanceof ViewGroup){ViewGroup g=(ViewGroup)view;for(int i=0;i<g.getChildCount();i++)if(findTextContaining(g.getChildAt(i),text))return true;}return false;}

 void catalogUpdate()throws Exception{
  String id="7660134591012817982";LocalLibrary db=new LocalLibrary(getTargetContext());JSONArray stored=db.directory(id);assertTrue(stored!=null,"existing cached catalog");JSONArray old=new JSONArray();for(int i=0;i<Math.min(611,stored.length());i++)old.put(stored.getJSONObject(i));JSONObject position=db.progress(id);NovelApi api=new NovelApi(getTargetContext(),db);JSONArray latest=api.directory(id,true);record("cached_vs_live_catalog",new JSONObject().put("cached",old.length()).put("live",latest.length()).put("last_live_title",latest.getJSONObject(latest.length()-1).getString("title")));db.directory(id,old);assertTrue(latest.length()>old.length(),"server has newer chapters than cached catalog");
  launchMain();try{reader=(ReaderActivity)startActivitySync(new Intent(getTargetContext(),ReaderActivity.class).putExtra("book_id",id).putExtra("book_name","穿越乱世：每天一份拼好饭").addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));ready();assertTrue(reader.directory.length()==old.length(),"reproduce stale local catalog");
  ui(()->{ReaderSurface.Frame f=reader.surface.frame;reader.commit(new ReaderSurface.Frame(f.id,f.title,reader.index,f.totalChapters,f.layout,f.layout.pages.size()-1));reader.surface.turn(1);});
  waitFor(()->reader.index>=old.length()&&!reader.busy,40,"next page discovers and opens newly published chapter");ready();assertTrue(reader.directory.length()==latest.length(),"catalog refreshed");assertTrue(reader.index==old.length(),"first newly published chapter");assertTrue(!reader.chapter.optString("text").isEmpty(),"real new chapter readable");record("old_end_turn_opens_new_chapter",new JSONObject().put("index",reader.index).put("title",reader.chapter.optString("title")).put("total",reader.directory.length()));shot("updated-chapter");
  ReaderActivity.DirectorySource actual=reader.directorySource;int at=reader.index;java.util.concurrent.atomic.AtomicInteger attempts=new java.util.concurrent.atomic.AtomicInteger();reader.directorySource=(book,force)->{assertTrue(force,"end check bypasses disk cache");attempts.incrementAndGet();throw new IOException("controlled offline");};ui(()->{ReaderSurface.Frame f=reader.surface.frame;reader.commit(new ReaderSurface.Frame(f.id,f.title,reader.index,f.totalChapters,f.layout,f.layout.pages.size()-1));reader.surface.turn(1);reader.surface.turn(1);});waitFor(()->!reader.refreshingDirectory&&reader.retry!=null,5,"failed update exposes retry");assertTrue(attempts.get()==1&&reader.index==at&&!reader.busy,"duplicate check suppressed and failure keeps body");record("refresh_failure_preserves_body_and_retry",true);
  reader.directorySource=(book,force)->latest;ui(()->reader.retry.run());waitFor(()->!reader.refreshingDirectory&&reader.notice.getText().toString().contains("暂无更新"),5,"unchanged catalog says latest only after successful check");assertTrue(reader.index==at&&reader.surface.frame.totalChapters==latest.length(),"unchanged catalog preserves chapter and total");record("retry_success_and_genuine_end",true);reader.directorySource=actual;
  }finally{if(reader!=null)ui(()->reader.finish());
  // Preserve the user's original text location while keeping the refreshed total.
  db.progress(id,position.optString("chapter"),position.optInt("offset"),position.optInt("index"),latest.length(),position.optString("title"));}waitFor(()->main.hasWindowFocus(),5,"home returns");ui(()->main.render());shot("updated-home");record("user_position_preserved_updated_total",new JSONObject().put("chapter",position.optString("chapter")).put("offset",position.optInt("offset")).put("total",latest.length()));
 }


 public void onStart(){output=new File(getTargetContext().getFilesDir(),"device-evidence");output.mkdirs();Bundle result=new Bundle();try{protocol();storage();if("true".equals(args.getString("refresh_search"))){SharedPreferences prefs=getTargetContext().getSharedPreferences("api_profiles",0);String original=prefs.getString("search","");try(Writer out=new OutputStreamWriter(new FileOutputStream(new File(output,"search-profile-before-refresh.json")),"UTF-8")){out.write(original);}prefs.edit().remove("search").commit();record("search_profile_reinitialized_for_diagnosis",true);}if("catalog-update".equals(args.getString("phase")))catalogUpdate();else if("improvements".equals(args.getString("phase")))improvements();else if("home".equals(args.getString("phase")))homeFlow();else if("nav".equals(args.getString("phase")))navigationCaptions();else if("recovery".equals(args.getString("phase")))contentRecovery();else if("probe".equals(args.getString("phase")))contentProbe();else if("resume".equals(args.getString("phase")))coldResume();else{if(!"ui".equals(args.getString("phase")))api();if(!"api".equals(args.getString("phase")))flow();}result.putString("stream","PASS "+checks.length()+" checks\n"+output);write(null);finish(Activity.RESULT_OK,result);}catch(Throwable e){try{record("failure",android.util.Log.getStackTraceString(e));shot("failure");write(e);}catch(Exception ignored){}result.putString("stream","FAIL "+android.util.Log.getStackTraceString(e));finish(Activity.RESULT_CANCELED,result);}}
 void write(Throwable error)throws Exception{try(Writer w=new OutputStreamWriter(new FileOutputStream(new File(output,"catalog-update".equals(args.getString("phase"))?"catalog-update-results.json":"improvements".equals(args.getString("phase"))?"improvements-results.json":"resume".equals(args.getString("phase"))?"cold-results.json":"recovery".equals(args.getString("phase"))?"recovery-results.json":"probe".equals(args.getString("phase"))?"probe-results.json":"nav".equals(args.getString("phase"))?"navigation-results.json":"home".equals(args.getString("phase"))?"home-results.json":"device-results.json")),"UTF-8")){w.write(new JSONObject().put("device",Build.MODEL).put("sdk",Build.VERSION.SDK_INT).put("success",error==null).put("checks",checks).toString(2));}}
